:root {
  --card-bg: #ffffff;
  --header-bg: #fff7ed;
  --header-border: #fed7aa;
  --pet-avatar-bg: #ffedd5;
  --pet-avatar-border: #fb923c;
  --pet-name-color: #7c2d12;
  --pet-breed-color: #9a3412;
  --badge-bg: #dcfce7;
  --badge-text: #166534;
  --badge-border: #86efac;
  --stat-bg: #fff7ed;
  --stat-border: #fed7aa;
  --stat-value-color: #ea580c;
  --stat-label-color: #78716c;
  --trait-bg: #fef3c7;
  --trait-text: #92400e;
  --trait-border: #fcd34d;
  --desc-color: #57534e;
  --footer-border: #e7e5e4;
  --shelter-color: #78716c;
  --btn-bg: #ea580c;
  --btn-text: #ffffff;
  --btn-hover-bg: #c2410c;
  --card-border: #e7e5e4;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  margin: 0;
  padding: 20px;
  box-sizing: border-box;
}

.card {
  background: var(--card-bg);
  border: 1px solid var(--card-border);
  border-radius: 16px;
  width: 480px;
  overflow: hidden;
}

.card-header {
  background: var(--header-bg);
  border-bottom: 1px solid var(--header-border);
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 16px 20px;
}

.pet-avatar {
  width: 64px;
  height: 64px;
  background: var(--pet-avatar-bg);
  border: 2px solid var(--pet-avatar-border);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 32px;
  flex-shrink: 0;
}

.pet-info {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.pet-name {
  font-size: 22px;
  font-weight: 700;
  color: var(--pet-name-color);
  line-height: 1.1;
}

.pet-breed {
  font-size: 13px;
  font-weight: 500;
  color: var(--pet-breed-color);
}

.status-badge {
  display: inline-block;
  background: var(--badge-bg);
  color: var(--badge-text);
  border: 1px solid var(--badge-border);
  border-radius: 20px;
  font-size: 11px;
  font-weight: 600;
  padding: 2px 10px;
  width: fit-content;
}

.stats-row {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
  padding: 14px 20px;
  border-bottom: 1px solid var(--footer-border);
}

.stat {
  background: var(--stat-bg);
  border: 1px solid var(--stat-border);
  border-radius: 10px;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 8px 4px;
  gap: 2px;
}

.stat-value {
  font-size: 18px;
  font-weight: 700;
  color: var(--stat-value-color);
  line-height: 1;
}

.stat-label {
  font-size: 11px;
  color: var(--stat-label-color);
  font-weight: 500;
}

.traits {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  padding: 12px 20px;
  border-bottom: 1px solid var(--footer-border);
}

.trait {
  background: var(--trait-bg);
  color: var(--trait-text);
  border: 1px solid var(--trait-border);
  border-radius: 20px;
  font-size: 12px;
  font-weight: 600;
  padding: 3px 10px;
}

.desc {
  font-size: 13px;
  color: var(--desc-color);
  line-height: 1.55;
  padding: 12px 20px;
  border-bottom: 1px solid var(--footer-border);
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 20px;
}

.shelter-info {
  font-size: 12px;
  font-weight: 500;
  color: var(--shelter-color);
}

.adopt-btn {
  background: var(--btn-bg);
  color: var(--btn-text);
  border: none;
  border-radius: 8px;
  font-size: 13px;
  font-weight: 700;
  padding: 8px 18px;
  cursor: pointer;
}

.adopt-btn:hover {
  background: var(--btn-hover-bg);
}
